package via

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"strings"
	"sync"
	"unicode"
)

// The keyboards, generated by scripts/genvia.ts from VIA's definitions
// (github.com/the-via/keyboards, GPL-3.0): USB IDs, switch matrix, the
// key drawing and the lighting controls.
//
//go:embed data/keyboards.json.gz
var catalogGz []byte

type rawModel struct {
	Name     string   `json:"name"`
	VID      uint16   `json:"vid"`
	PID      uint16   `json:"pid"`
	Rows     int      `json:"rows"`
	Cols     int      `json:"cols"`
	Width    int      `json:"width"`
	Height   int      `json:"height"`
	Keys     [][6]int `json:"keys"` // row, col, x, y, w, h
	Lighting *struct {
		Brightness []int    `json:"brightness"` // channel, ID, max
		Effect     []int    `json:"effect"`     // channel, ID
		Effects    [][2]any `json:"effects"`    // value, name
		Speed      []int    `json:"speed"`
		Color      []int    `json:"color"`
	} `json:"lighting"`
}

func value(v []int) *Value {
	if len(v) < 2 {
		return nil
	}
	out := &Value{Channel: byte(v[0]), ID: byte(v[1]), Max: 255}
	if len(v) > 2 && v[2] > 0 && v[2] <= 255 {
		out.Max = v[2]
	}
	return out
}

// Models are the keyboards of the definitions, by USB IDs: VIA's own first,
// then vendors' sharing them. Loaded on first use.
var Models = sync.OnceValue(func() map[[2]uint16][]*Model {
	z, err := gzip.NewReader(bytes.NewReader(catalogGz))
	if err != nil {
		panic(err)
	}
	var raw []rawModel
	if err := json.NewDecoder(z).Decode(&raw); err != nil {
		panic(err)
	}
	out := make(map[[2]uint16][]*Model, len(raw))
	for _, r := range raw {
		m := &Model{Name: r.Name, VID: r.VID, PID: r.PID, Rows: r.Rows, Cols: r.Cols, Width: r.Width, Height: r.Height}
		for _, k := range r.Keys {
			if k[0] < 0 || k[1] < 0 || k[0] >= r.Rows || k[1] >= r.Cols {
				continue
			}
			m.Keys = append(m.Keys, Key{Row: k[0], Col: k[1], X: k[2], Y: k[3], W: k[4], H: k[5]})
		}
		if l := r.Lighting; l != nil {
			m.Light = &Lighting{Brightness: value(l.Brightness), Effect: value(l.Effect), Speed: value(l.Speed), Color: value(l.Color)}
			for _, e := range l.Effects {
				v, _ := e[0].(float64)
				n, _ := e[1].(string)
				m.Light.Effects = append(m.Light.Effects, Effect{int(v), n})
			}
		}
		id := [2]uint16{r.VID, r.PID}
		out[id] = append(out[id], m)
	}
	return out
})

// Pick returns the best-matching model among those sharing USB IDs, and
// whether the choice is unsure (several models share the IDs and none or more
// than one matched the product name best).
func Pick(models []*Model, product string) (*Model, bool) {
	words := func(s string) map[string]bool {
		out := map[string]bool{}
		for _, w := range strings.FieldsFunc(strings.ToLower(s), func(r rune) bool { return !unicode.IsLetter(r) && !unicode.IsDigit(r) }) {
			if len(w) >= 2 {
				out[w] = true
			}
		}
		return out
	}
	have := words(product)
	best, score, tied := models[0], 0, false
	for _, m := range models {
		n := 0
		for w := range words(m.Name) {
			if have[w] {
				n += len(w)
			}
		}
		if n > score {
			best, score, tied = m, n, false
		} else if n > 0 && n == score {
			tied = true
		}
	}
	return best, len(models) > 1 && (score == 0 || tied)
}
